function record(magic,size,fields,version=1){const b=Buffer.alloc(size);b.write(magic);b.writeUInt16LE(version,4);b.writeUInt16LE(1,6);b.writeUInt32LE(size,8);fields.forEach((v,i)=>b.writeUInt32LE(v>>>0,16+4*i));return b;}
const words=a=>{const b=Buffer.alloc(a.length*4);a.forEach((v,i)=>b.writeUInt32LE(v>>>0,4*i));return b;};
const state=c=>record('R3ST',56,[...c.registers,c.pc,c.flags]);
const exit=(reason,count,f,version=2)=>record('R3EX',40,[reason,count,f?.detail??0,f?.address??0,f?.access??0,f?4:0],version);
const helper=(value=0,f)=>record('R3MH',40,[f?1:0,f?0:value,f?.detail??0,f?.address??0,f?.access??0,f?4:0]);
const arena=c=>Buffer.from(new Uint8Array(c.memory.buffer,c.base,SIZE));
function capture(c,label){const b=arena(c),row={context:c.ordinal,label,offset:frames.length*SIZE,bytes:SIZE,sha256:hash(b)};frames.push(b);return row;}
function cpu(c){const b=arena(c);return{registers:Array.from({length:8},(_,i)=>b.readUInt32LE(16+4*i)),pc:b.readUInt32LE(48),flags:b.readUInt32LE(52)};}
function input(c,offset,b,label){const before=capture(c,'before input '+label);new Uint8Array(c.memory.buffer).set(b,c.base+offset);journal.push({context:c.ordinal,name:'input',offset,hex:b.toString('hex'),label,before,after:capture(c,'after input '+label)});}
function host(c,name,args,label=name){const before=capture(c,'before '+label),old=arena(c);assert.equal(c.api[name](...args),0,label);assert.deepEqual(arena(c).subarray(0,56),old.subarray(0,56),label+' CPU neutral');assert.deepEqual(arena(c).subarray(FP),old.subarray(FP),label+' FP neutral');
 if(name==='map'||name==='unmap'){const[start,pages]=args;for(const address of c.known.keys())if(address>=start&&address<start+4096*pages)c.known.delete(address);}
 const row={context:c.ordinal,name,args,label,before,after:capture(c,'after '+label)};journal.push(row);return row;}
function upload(c,address,b){input(c,TRANSFER,b,'declared RAM upload');host(c,'upload',[address,b.length]);for(let i=0;i<b.length;i++)c.known.set(address+i,b[i]);}
const put=(c,address,value)=>upload(c,address,words([value]));
function known(c,address,length){return Buffer.from(Array.from({length},(_,i)=>c.known.get(address+i)??0));}
function readWord(c,address,label){const row=host(c,'read32',[address],label),value=arena(c).readUInt32LE(120);assert.deepEqual(arena(c).subarray(100,140),helper(value));assert.equal(value,known(c,address,4).readUInt32LE(0),label+' declared DWORD');ram.push({context:c.ordinal,label,address,bytes:4,hex:words([value]).toString('hex'),reads:[row]});return value;}
function readBytes(c,address,length,label){const b=Buffer.alloc(length),reads=[];for(let i=0;i<length;i++){reads.push(host(c,'read8',[address+i],label+' byte'+i));b[i]=arena(c).readUInt32LE(120);assert.deepEqual(arena(c).subarray(100,140),record('R3MH',40,[0,b[i],0,0,0,1],2));}assert.deepEqual(b,known(c,address,length),label+' declared sentinels');ram.push({context:c.ordinal,label,address,bytes:length,hex:b.toString('hex'),reads});return b;}
function seed(c,r,pc,flags){const b=Buffer.alloc(140);b.set(state({registers:r,pc,flags}));b.set(exit(3,0),56);b.set(helper(0xdecafbad),100);input(c,0,b,'explicit CPU seed');return cpu(c);}
function run(c,u,budget,label,next,reason=1,count=1,f,status=0,memoryTarget=true,version=2){const before=capture(c,'before generated '+label),expected=arena(c);if(status===0){expected.set(state(next));expected.set(exit(reason,count,f,version),56);if(f||(memoryTarget&&count))expected.set(helper(0,f),100);}const actual=u.run(c.base,c.base+56,budget,c.base+96);assert.equal(actual,status,label);assert.deepEqual(arena(c),expected,'full4364 '+label);generated++;retired+=status===0?count:0;const row={context:c.ordinal,name:'run',label,budget,status:actual,before,after:capture(c,'after generated '+label)};journal.push(row);return row;}
function selected(base,index){return Number(BigInt.asUintN(32,BigInt(base)+4n*(BigInt(index)>>5n)));}
function mutate(kind,word,bit){const mask=(2**bit)>>>0;return(kind==='bts'?(word|mask):kind==='btr'?(word&~mask):(word^mask))>>>0;}
function target(c,u,address,raw,label,length=3,reason=1){const before=cpu(c),old=readWord(c,address,'before '+label),bit=raw&31,cf=(old>>>bit)&1,next={registers:[...before.registers],pc:(before.pc+length)>>>0,flags:(before.flags&0x442)|cf};const row=run(c,u,1,label,next,reason),value=mutate(c.kind.name,old,bit);for(let i=0;i<4;i++)c.known.set(address+i,(value>>>(8*i))&255);const observed=readWord(c,address,'after '+label);assert.equal(observed,value);targets.push({context:c.ordinal,kind:c.kind.name,owner:c.owner,entries:c.entries,label,address,raw,old_word:old,value,old_cpu:before,next,run:row});return row;}
function program(kind){const forms=[[0x0f,kind.opcode,0x0b],[0x0f,kind.opcode,0x00],[0x0f,kind.opcode,0x4c,0x8a,0x80],...immediates.map(raw=>[0x0f,0xba,(kind.extension<<3)|3,raw]),[0xb9,32,0,0,0,0x0f,kind.opcode,0x0b]],wanted=Buffer.alloc(128,0xcc),specs=[];for(const[i,form]of forms.entries()){const at=i*16;wanted.set(form,at);wanted[at+form.length]=0xe9;wanted.writeInt32LE(COLD-(PC+at+form.length+5),at+form.length+1);specs.push([PC+at,form.length+5]);}const saved=readFileSync(join(output,kind.name+'.x86'));assert.deepEqual(saved,wanted,'independent Rust/JS bank');return{saved,forms,specs};}
function bind(c,specs,entries){input(c,TRANSFER,words(entries?specs.map(s=>s[0]):specs.flat()),'compile descriptors');const name=c.owner==='replacement'?(entries?'compile_entries':'compile'):(entries?'compile_resident_entries':'compile_resident');host(c,name,entries?[specs.length,0]:[specs.length]);if(c.owner==='replacement')return{generation:c.api.generation(),pointer:c.api.module_ptr()>>>0,length:c.api.module_len()>>>0};const b=arena(c);return Object.fromEntries(['low','high','pointer','length'].map((name,i)=>[name,b.readUInt32LE(148+4*i)]));}
function install(c,binding,tail=false){const bytes=Buffer.from(new Uint8Array(c.memory.buffer,binding.pointer,binding.length)),module=new WebAssembly.Module(bytes),guard=c.owner==='replacement'?'guard':'guard_resident',names=tail?[guard]:[guard,'read32',c.owner==='replacement'?'store32':'store_resident32'];assert.deepEqual(WebAssembly.Module.imports(module),[{module:'env',name:'memory',kind:'memory'},...names.map(name=>({module:'ring3',name,kind:'function'}))]);const file=`${c.kind.name}-${c.owner}-${c.entries?'entries':'extent'}${tail?'-tail':''}.wasm`;writeFileSync(join(output,file),bytes,{flag:'wx'});modules.push({context:c.ordinal,kind:c.kind.name,owner:c.owner,entries:c.entries,tail,file,...binding,bytes:bytes.length,sha256:hash(bytes),specs:tail?[[PC+3,5]]:c.program.specs,imports:names});return{...binding,run:new WebAssembly.Instance(module,{env:{memory:c.memory},ring3:c.api}).exports.run};}
function open(kind,owner,entries){const instance=new WebAssembly.Instance(engine.module,{}),c={ordinal:++contexts,kind,owner,entries,memory:instance.exports.memory,api:{},known:new Map(),program:program(kind)};for(const name of['open','close','arena_ptr','map','unmap','protect','upload','read8','read32','compile','compile_entries','compile_resident','compile_resident_entries','generation','module_ptr','module_len','guard','guard_resident','store32','store_resident32']){c.api[name]=instance.exports['ring3_abi_v1_'+name];assert.equal(typeof c.api[name],'function');}assert.equal(c.api.open(8,c.ordinal,0xc9526000),0);c.base=c.api.arena_ptr()>>>0;assert.deepEqual(arena(c).subarray(0,FP),initial.subarray(0,FP),'fresh arena initialized headers; custom FP is a later declared input');input(c,0,initial,'complete initial arena with opaque FP');for(const args of[[PC,1,7],[DATA,2,3],[0xfffff000,1,3],[0,1,3],[0xf0005000,1,3],[0x10005000,1,3]])host(c,'map',args);upload(c,PC,c.program.saved);const u=install(c,bind(c,c.program.specs,entries));return[c,u];}
function close(c,u){const before=capture(c,'before close');assert.equal(c.api.close(),0);journal.push({context:c.ordinal,name:'close',args:[],before});assert.equal(u.run(c.base,c.base+56,1,c.base+96),5);generated++;closed++;journal.push({context:c.ordinal,name:'closed-run',status:5,budget:1,label:'status only; no post-close module pointer or retained-arena inspection'});}
const REG=[0xa53c0011,0,0x3456789a,BASE,0x9000,0x56789abc,0x6789abcd,0x789abcde];
for(const kind of kinds)for(const owner of['replacement','resident'])for(const entries of[false,true]){
 const[c,u]=open(kind,owner,entries);seed(c,REG,PC,2);const beforeFrame=capture(c,'before invalid pointer'),before=arena(c),status=u.run(0xffffffff,c.base+56,1,c.base+96);assert.equal(status,1);assert.deepEqual(arena(c),before);journal.push({context:c.ordinal,name:'preflight',status,before:beforeFrame,after:capture(c,'after invalid pointer')});generated++;stats.preflight++;
 run(c,u,0,'zero budget before memory',cpu(c),1,0);input(c,96,words([1]),'declared cancel');run(c,u,1,'cancel before memory',cpu(c),2,0);input(c,96,words([0]),'clear declared cancel');stats.controls+=2;
 for(const index of indexes)for(const oldBit of[0,1]){const r=[...REG];r[1]=index>>>0;const address=selected(BASE,index),old=oldBit?(2**(index&31))>>>0:0;put(c,address,old);seed(c,r,PC,oldBit?2:0xcd7);target(c,u,address,index,'core signed current index');stats.core++;}
 for(const[form,raw]of immediates.entries())for(const oldBit of[0,1]){const r=[...REG];r[1]=0x80000000;const old=oldBit?(2**(raw&31))>>>0:0;put(c,BASE,old);seed(c,r,PC+(form+3)*16,oldBit?2:0xcd7);target(c,u,BASE,raw,'core immediate low5 no offset',4);stats.core++;}
 for(const form of[1,2]){const r=[...REG];let address,index;if(form===1){r[0]=BASE;index=BASE;address=selected(BASE,index);}else{r[2]=BASE+128;r[1]=33;index=33;address=BASE+136;}put(c,address,(2**(index&31))>>>0);seed(c,r,PC+form*16,0xcd7);target(c,u,address,index,'old EA/index register alias',c.program.forms[form].length);stats.aliases++;}
 for(const[base,index,address]of[[0x5ffd,0,0x5ffd],[0xfffffffc,0,0xfffffffc],[0xfffffff0,128,0],[0,-1,0xfffffffc],[0x6000,-33,0x5ff8]]){assert.equal(selected(base,index),address);const r=[...REG];r[3]=base;r[1]=index>>>0;put(c,address,1);seed(c,r,PC,0xcd7);target(c,u,address,index,'unaligned crossing selected-address wrap');stats.boundaries++;}
 const cases=[{name:'unmapped first read',address:BASE,page:DATA,detail:1,access:1,sentinel:[0x6080,4]},
 {name:'denied first read',address:BASE,page:DATA,detail:2,access:1,bits:2,sentinel:[0x6080,4]},
 {name:'readable denied write',address:BASE,page:DATA,detail:2,access:2,bits:1,sentinel:[BASE-1,6]},
 {name:'cross second page unmapped read',address:0x5ffd,page:0x6000,detail:1,access:1,sentinel:[0x5ffc,4]},
 {name:'cross second page readable denied write',address:0x5ffd,page:0x6000,detail:2,access:2,bits:1,sentinel:[0x5ffc,6]},
 ...[0xfffffffd,0xfffffffe,0xffffffff].map(address=>({name:'DWORD span overflow',address,detail:3,access:1,sentinel:[0xfffffffc,4]}))];
 for(const f of cases){upload(c,f.sentinel[0],Buffer.alloc(f.sentinel[1],0x55));if(f.page!==undefined)put(c,f.address,1);if(f.page!==undefined)host(c,f.detail===1?'unmap':'protect',[f.page,1,...(f.detail===1?[]:[f.bits])]);readBytes(c,...f.sentinel,'fault surviving sentinels before');const r=[...REG];r[3]=f.address;r[1]=0;seed(c,r,PC,0xcd7);const fault={detail:f.detail,address:f.page===0x6000?0x6000:f.address,access:f.access};const calls=[];for(let n=0;n<2;n++){calls.push(run(c,u,1,f.name+' retained attempt'+n,cpu(c),5,0,fault));readBytes(c,...f.sentinel,'fault surviving sentinels after');stats.fault_calls++;}faults.push({context:c.ordinal,...f,calls});if(f.page!==undefined){host(c,f.detail===1?'map':'protect',[f.page,1,3]);readWord(c,f.address,'repaired permissions/maps before declared RAM edit');put(c,f.address,4);target(c,u,f.address,0,'sameCPU repair rereads current word');stats.repairs++;}}
 put(c,BASE+4,1);host(c,'protect',[DATA,1,1]);const r=[...REG];r[1]=0xffffffdf;seed(c,r,PC+112,0xcd7);const current={registers:[...r],pc:PC+117,flags:0xcd7};current.registers[1]=32;const writeFault={detail:2,address:BASE+4,access:2};run(c,u,9,'MOV current index retires before checked write fault',current,5,1,writeFault);run(c,u,9,'retained mutation fault without replay',current,5,0,writeFault);stats.fault_calls+=2;host(c,'protect',[DATA,1,3]);readWord(c,BASE+4,'failed store preserves old word');put(c,BASE+4,4);assert.deepEqual(cpu(c),current,'host RAM/protect repair keeps retired prefix CPU');target(c,u,BASE+4,32,'sameCPU prefix repair current ECX/new RAM');run(c,u,1,'retained JMP after repaired mutation',{...cpu(c),pc:COLD},1,1,undefined,0,false);run(c,u,1,'cold after retained JMP',cpu(c),3,0,undefined,0,false);stats.prefix_repairs++;
 const smcIndex=kind.name==='bts'?0:kind.name==='btr'?4:16,smcWord=c.program.saved.readUInt32LE(0),smcRegs=[...REG];smcRegs[3]=PC;smcRegs[1]=smcIndex;seed(c,smcRegs,PC,2);const oldAllocation=Buffer.from(new Uint8Array(c.memory.buffer,u.pointer,u.length));target(c,u,PC,smcIndex,'same/different code write commits before invalidation',3,6);stats.smc++;run(c,u,1,'stale owner neutral',cpu(c),1,0,undefined,4);assert.deepEqual(Buffer.from(new Uint8Array(c.memory.buffer,u.pointer,u.length)),oldAllocation,'immediate live old allocation after stale call before getters/allocation');const tail=install(c,bind(c,[[PC+3,5]],false),true);run(c,tail,2,'fresh current tail no CPU repair',{...cpu(c),pc:COLD},3,1,undefined,0,false,1);close(c,tail);
}
